def _detect_line_ending(source: IO[str]) -> str:
    content = source.read()
    source.seek(0)
    for i, ch in enumerate(content):
        if ch == "\n":
            return "\r\n" if i > 0 and content[i - 1] == "\r" else "\n"
        if ch == "\r":
            return "\r\n" if i + 1 < len(content) and content[i + 1] == "\n" else "\n"
    return "\n"
